PrologProcedure:
#Region WFP Generate Hiring Plan — hire and leave months for the generated roster
# pStage = feb : the plan as it stood at the Feb 2026 close (run this, then snapshot)
# pStage = now : today's plan — some hires slipped further, more approvals, a few
#               more leavers. Forecast vs the Feb snapshot then shows real movement.
# Only touches generated positions (number 1001+); the hand-typed demo lines
# (WFP Seed Hiring Plan) are left alone. Every generated line is written in full
# (zeros and blanks included), so a re-run is idempotent.
# Deterministic per position: the generator is seeded from the position number.
#   Budget   — every open role hired in its target month, approved at budget sign-off;
#              9% of filled roles leave over Apr 2026 .. Dec 2027
#   Forecast — 45% of hires slip 1-3 months; near-term hires mostly approved;
#              12% leave (same months as Budget where both apply)
#   Downside — Forecast hires two months later; 17% leave
cDim = 'WFP Position';
cHP  = 'WFP Hiring Plan';
cPer = 'WFP Period';
nLcgA = 9301; nLcgC = 49297; nLcgM = 233280;
nNow = IF( pStage @= 'now', 1, 0 );

nN = DIMSIZ( cDim );
nI = 1;
WHILE( nI <= nN );
   vPos = DIMNM( cDim, nI );
   nDash = SCAN( '-', vPos );
   nNum = IF( DTYPE( cDim, vPos ) @= 'N' & nDash > 0, NUMBR( SUBST( vPos, nDash + 1, 10 ) ), 0 );
   IF( nNum >= 1001 );
      nX = nNum * 7919 + 104729; nSeed = nX - INT( nX / nLcgM ) * nLcgM;
      nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR1 = nSeed / nLcgM;
      nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR2 = nSeed / nLcgM;
      nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR3 = nSeed / nLcgM;
      nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR4 = nSeed / nLcgM;
      nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR5 = nSeed / nLcgM;
      nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR6 = nSeed / nLcgM;
      nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR7 = nSeed / nLcgM;
      nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR8 = nSeed / nLcgM;

      vStatus = ATTRS( cDim, vPos, 'Position Status' );
      nBH = 0; nFH = 0; nDH = 0; nBL = 0; nFL = 0; nDL = 0;
      vFA = ''; vFBy = ''; vFAt = '';

      IF( vStatus @= 'Open Req' % vStatus @= 'TBH' );
         nBH = IF( vStatus @= 'Open Req', ATTRN( cPer, ATTRS( cDim, vPos, 'Start Period' ), 'Period Index' ), 16 + INT( nR1 * 15 ) );
         nFH = nBH + IF( nR2 < 0.45, 1 + INT( nR3 * 3 ), 0 );
         IF( nNow = 1 & nR5 < 0.20 );
            nFH = nFH + 1 + INT( nR6 * 2 );
         ENDIF;
         nFH = IF( nFH > 36, 36, nFH );
         nDH = IF( nFH + 2 > 36, 36, nFH + 2 );
         # approvals: near-term hires mostly signed off by Feb; more since
         IF( ( nFH <= 19 & nR4 < 0.70 ) % nR4 < 0.15 );
            vFA = 'Y'; vFBy = 'Admin'; vFAt = '2026-02-26T10:00:00';
         ELSEIF( nNow = 1 & ( ( nFH <= 21 & nR4 < 0.85 ) % nR4 < 0.25 ) );
            vFA = 'Y'; vFBy = 'Admin'; vFAt = '2026-10-15T09:30:00';
         ENDIF;
      ELSEIF( vStatus @= 'Filled' & ATTRS( cDim, vPos, 'End Period' ) @= '' );
         nLeave = 16 + INT( nR7 * 21 );
         nBL = IF( nR6 < 0.09, nLeave, 0 );
         nFL = IF( nR6 < 0.12, nLeave, 0 );
         IF( nNow = 1 & nFL = 0 & nR6 < 0.14 );
            nFL = 16 + INT( nR8 * 9 );
         ENDIF;
         nDL = IF( nR6 < 0.17, IF( nFL > 0, nFL, nLeave ), 0 );
      ENDIF;

      CellPutN( nBH, cHP, 'Budget',   vPos, 'Hire Month' );
      CellPutN( nBL, cHP, 'Budget',   vPos, 'Attrition Month' );
      CellPutS( IF( nBH > 0, 'Y', '' ),                     cHP, 'Budget', vPos, 'Approved' );
      CellPutS( IF( nBH > 0, 'Budget sign-off', '' ),       cHP, 'Budget', vPos, 'Approved By' );
      CellPutS( IF( nBH > 0, '2025-11-28T17:00:00', '' ),   cHP, 'Budget', vPos, 'Approved At' );

      CellPutN( nFH, cHP, 'Forecast', vPos, 'Hire Month' );
      CellPutN( nFL, cHP, 'Forecast', vPos, 'Attrition Month' );
      CellPutS( vFA,  cHP, 'Forecast', vPos, 'Approved' );
      CellPutS( vFBy, cHP, 'Forecast', vPos, 'Approved By' );
      CellPutS( vFAt, cHP, 'Forecast', vPos, 'Approved At' );

      CellPutN( nDH, cHP, 'Downside', vPos, 'Hire Month' );
      CellPutN( nDL, cHP, 'Downside', vPos, 'Attrition Month' );
      CellPutS( vFA,  cHP, 'Downside', vPos, 'Approved' );
      CellPutS( vFBy, cHP, 'Downside', vPos, 'Approved By' );
      CellPutS( vFAt, cHP, 'Downside', vPos, 'Approved At' );
   ENDIF;
   nI = nI + 1;
END;
#EndRegion
